// Generates src/ui/icon-data.ts from the Solar icon set (480 Design, CC BY 4.0) so the app ships only
// the icons it uses, bundled and offline. Add or swap icons in NAME_MAP and re-run:
//   node scripts/build-icons.mjs
// Never hand-edit the generated file.
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const solar = require('@iconify-json/solar/icons.json');
const brands = JSON.parse(readFileSync(new URL('./brand-paths.json', import.meta.url), 'utf8'));

/** app icon name -> Solar icon name (line = "-linear", filled = "-bold"). */
const NAME_MAP = {
  arrowRight: 'arrow-right',
  arrowUp: 'arrow-up',
  back: 'alt-arrow-left',
  bell: 'bell',
  bookmark: 'bookmark',
  camera: 'camera',
  caretDown: 'alt-arrow-down',
  caretRight: 'alt-arrow-right',
  chat: 'chat-round-dots',
  chats: 'chat-dots',
  check: 'check-circle',
  checks: 'check-read',
  tick: 'check',
  close: 'close',
  device: 'smartphone',
  dots: 'menu-dots',
  flag: 'flag',
  flash: 'bolt',
  flip: 'camera-rotate',
  friends: 'users-group-two-rounded',
  gear: 'settings',
  globe: 'global',
  grid: 'widget',
  heart: 'heart',
  home: 'home-smile',
  images: 'gallery',
  lock: 'lock-keyhole',
  mail: 'letter',
  music: 'music-note',
  pencil: 'pen',
  phone: 'phone',
  plus: 'add-circle',
  profile: 'user-circle',
  reply: 'undo-left-round',
  search: 'magnifer',
  send: 'plain',
  share: 'share',
  sparkle: 'stars',
  sun: 'sun-2',
  tap: 'cursor',
  timer: 'stopwatch',
  translate: 'translation',
  users: 'users-group-rounded',
  map: 'map',
  pin: 'map-point',
  gps: 'gps',
  history: 'history',
  userPlus: 'user-plus',
  galleryAdd: 'gallery-add',
  pause: 'pause',
  play: 'play',
  // reactions
  fire: 'fire',
  laugh: 'emoji-funny-circle',
  wow: 'confounded-circle',
  sad: 'sad-circle',
  bravo: 'hand-stars',
};

const body = (name) => {
  const icon = solar.icons[name] ?? solar.icons[solar.aliases?.[name]?.parent];
  if (!icon) throw new Error(`Solar icon not found: ${name}`);
  return icon.body;
};

const out = {};
for (const [key, solarName] of Object.entries(NAME_MAP)) {
  out[key] = { vb: 24, line: body(`${solarName}-linear`), bold: body(`${solarName}-bold`) };
}
// Brand marks are not in Solar; single-path logos (viewBox 256) are filled with the current color.
for (const [key, paths] of Object.entries(brands)) {
  const svg = paths.map((d) => `<path fill="currentColor" d="${d}"/>`).join('');
  out[key] = { vb: 256, line: svg, bold: svg };
}

const header = `// GENERATED by scripts/build-icons.mjs — do not edit. Solar icons by 480 Design, CC BY 4.0.\n`;
writeFileSync(
  new URL('../src/ui/icon-data.ts', import.meta.url),
  `${header}export const ICON_DATA = ${JSON.stringify(out, null, 1)} as const;\n`,
);
console.log(`icon-data.ts: ${Object.keys(out).length} icons`);
